IF OBJECT_ID(N'[__EFMigrationsHistory]') IS NULL
BEGIN
    CREATE TABLE [__EFMigrationsHistory] (
        [MigrationId] nvarchar(150) NOT NULL,
        [ProductVersion] nvarchar(32) NOT NULL,
        CONSTRAINT [PK___EFMigrationsHistory] PRIMARY KEY ([MigrationId])
    );
END;

DECLARE @var sysname;
SELECT @var = [d].[name]
FROM [sys].[default_constraints] [d]
INNER JOIN [sys].[columns] [c] ON [d].[parent_column_id] = [c].[column_id] AND [d].[parent_object_id] = [c].[object_id]
WHERE ([d].[parent_object_id] = OBJECT_ID(N'[SubTasks]') AND [c].[name] = N'Title');
IF @var IS NOT NULL EXEC(N'ALTER TABLE [SubTasks] DROP CONSTRAINT [' + @var + '];');
ALTER TABLE [SubTasks] ALTER COLUMN [Title] nvarchar(250) NOT NULL;

IF OBJECT_ID(N'[__EFMigrationsHistory]') IS NULL
BEGIN
    CREATE TABLE [__EFMigrationsHistory] (
        [MigrationId] nvarchar(150) NOT NULL,
        [ProductVersion] nvarchar(32) NOT NULL,
        CONSTRAINT [PK___EFMigrationsHistory] PRIMARY KEY ([MigrationId])
    );
END;

CREATE TABLE [VoiceNoteContents] (
    [NoteId] nvarchar(450) NOT NULL,
    [TranscriptText] nvarchar(max) NULL,
    CONSTRAINT [PK_VoiceNoteContents] PRIMARY KEY ([NoteId]),
    CONSTRAINT [FK_VoiceNoteContents_Notes_NoteId] FOREIGN KEY ([NoteId]) REFERENCES [Notes] ([Id]) ON DELETE NO ACTION
);

DECLARE @var sysname;
SELECT @var = [d].[name]
FROM [sys].[default_constraints] [d]
INNER JOIN [sys].[columns] [c] ON [d].[parent_column_id] = [c].[column_id] AND [d].[parent_object_id] = [c].[object_id]
WHERE ([d].[parent_object_id] = OBJECT_ID(N'[FocusSessions]') AND [c].[name] = N'SpaceId');
IF @var IS NOT NULL EXEC(N'ALTER TABLE [FocusSessions] DROP CONSTRAINT [' + @var + '];');
ALTER TABLE [FocusSessions] ALTER COLUMN [SpaceId] nvarchar(450) NOT NULL;
